-- Rollback for iso-59014-md-verification-pack.sql (run 2026-09-08).
-- Reverts ONLY the rows that pack touched — identified both by explicit id list AND by the verification_note
-- tag — and ONLY for standard ISO-59014, joined through worksheet_templates -> standards.code so no other
-- standard can be reached. The 2026-09-08 prod export showed all 84 fields carrying the single prior status
-- 'imported_unverified' with verification_quote, verification_note and verified_at all null, so every row
-- returns to exactly that prior state. ISO-59014 has 0 equations, so there is no equations block.
-- Gates were NOT touched by the pack; the STAGED file was never applied; the encode-time source_quote column
-- is a different column and is left untouched.
-- No transaction control in this file: apply-pack.mjs supplies BEGIN/COMMIT and implements --dry-run by
-- rolling back. An inline commit would silently turn a dry run into a real apply.

-- ---- fields: 84 rows — prior status = imported_unverified ----
update public.fields f set verification_status='imported_unverified', verification_quote=null, verification_note=null, verified_at=null
  from public.worksheet_templates wt join public.standards s on s.id = wt.standard_id
 where wt.id = f.worksheet_template_id and s.code = 'ISO-59014'
   and f.id in ('29bd85ec-f851-4cba-af6f-8a86fb79b22e','b96b8ad7-69bd-4961-b6ce-436598e1ffd7','e473d488-03b3-4436-a415-2ace829e861f','479918eb-9d88-4fb3-9b31-bff7c3defc2e','49b6c4ba-e32a-4f83-a8d2-c778f9fa429c','32596345-f82a-4a47-9264-49f5ac5652e9','c1429389-d0d7-41a2-93eb-aa4a30864611','6831df58-c801-4bba-b0ad-4f5093c6928d','d1e3629d-31ac-4602-8795-ef0ebac08426','54f3903f-1b4f-4d7c-980c-07b915fce8fa','84177f85-b197-4c1d-8a9a-13cb1851f896','9d1e1f98-7f66-4bca-a8cb-b32cabdeec3a','6b1165ed-4645-4db2-ad4d-648a21d30c83','c149725f-b59f-41fe-b2df-f1f419b2777c','f78ce88d-1155-4477-acbd-d603492f973c','001e1322-8d81-4050-8042-63b5a2db69e4','45e8cc87-767f-4be1-a72b-6c9c964dd237','86b721ef-0bfb-46b0-bc71-0b8611e10ec3','5c00c14f-a40b-47fd-924b-ac966e086576','1aaf40c8-10ae-44d6-be21-171f8c0a906e','14691850-622c-428a-ad8e-c4806f021bb9','20b35ae5-ddf3-4099-bf32-f5af3658ba07','cd750d02-7552-4d97-a7f9-2487a6080ce8','b422cb1e-f4ff-4239-92bf-87acafca8d96','7b71dac6-0310-4a02-a92f-2cbf1f1ba6f7','774ccf7a-b290-4c6e-8f14-56d876f9b322','df435326-5868-42f9-9986-ef606c936dac','c75c3020-f0b0-4f3e-b5e0-b311a6d33927','4f7ac477-7951-4b8f-a6ce-8bb9ef285d6a','a911d0f6-31ec-4058-b10b-ded8298e6b7d','dad9735b-3a3b-4831-abfb-42ddeb82172c','60c224c3-c226-4a9c-bd8a-10108abdf22f','6c55c7e4-e211-4f47-8bc7-4db98db30543','8611fcb5-36c5-4ae6-b11b-b6ce5dc10946','34a44cf2-bfc2-4168-8bbb-86735f80e2c0','5636815c-5de0-4b59-8fbc-b7c558bb69a5','fbc06ad7-ee26-484f-b499-21bde531f595','8bfee415-bc80-4175-be13-881878e28b52','cd0a47dc-493f-4ffe-8d17-90f759b0587d','923e0a2e-5b35-4dcb-b017-14a6fdf62514','209078d1-afd0-4369-8da5-4eba7ec5df2a','e946f2d4-2970-4cbe-8204-4d873ae81cc9','ecc8ef61-dfee-4c70-be91-965919150b6c','f14ba1d7-d68d-4ed7-8622-07ff3053f802','da8a5982-5387-40fa-a8c7-295f1e17d31e','ad5365d2-0805-489b-9067-cc22a9683122','28e6272b-a1a5-4895-96d9-a7fe177eae72','86cbb4b8-1176-4020-b686-edf30ffcd001','470fa928-aff7-47dc-888f-c12f55ec6f25','9760c53d-7e4c-4246-a717-6c8c793f4a9a','e7ba2c2e-db29-4568-892e-ed2764030